package com.arrow.systemui.cc.controller;
import android.bluetooth.*;import android.content.*;import android.net.wifi.WifiManager;import android.provider.Settings;import android.widget.Toast;
public class ConnectivityController {private final Context c;private final WifiManager wifi;private final BluetoothAdapter bluetooth;public ConnectivityController(Context x){c=x;wifi=(WifiManager)x.getApplicationContext().getSystemService(Context.WIFI_SERVICE);BluetoothManager b=(BluetoothManager)x.getSystemService(Context.BLUETOOTH_SERVICE);bluetooth=b==null?BluetoothAdapter.getDefaultAdapter():b.getAdapter();}public boolean isWifiEnabled(){try{return wifi.isWifiEnabled();}catch(Exception e){return false;}}public boolean toggleWifi(){try{boolean ok=wifi.setWifiEnabled(!isWifiEnabled());if(!ok)openPanel(Settings.Panel.ACTION_WIFI);return ok;}catch(Exception e){openPanel(Settings.Panel.ACTION_WIFI);return false;}}public boolean isBluetoothEnabled(){try{return bluetooth!=null&&bluetooth.isEnabled();}catch(Exception e){return false;}}public boolean toggleBluetooth(){try{if(bluetooth==null){open(Settings.ACTION_BLUETOOTH_SETTINGS);return false;}return bluetooth.isEnabled()?bluetooth.disable():bluetooth.enable();}catch(Exception e){open(Settings.ACTION_BLUETOOTH_SETTINGS);return false;}}public boolean isAirplaneMode(){try{return Settings.Global.getInt(c.getContentResolver(),Settings.Global.AIRPLANE_MODE_ON,0)==1;}catch(Exception e){return false;}}public void openAirplaneSettings(){open(Settings.ACTION_AIRPLANE_MODE_SETTINGS);}public void openNetworkSettings(){open(Settings.ACTION_WIRELESS_SETTINGS);}public void openHotspotSettings(){open(Settings.ACTION_WIRELESS_SETTINGS);}public void openDndSettings(){open(Settings.ACTION_ZEN_MODE_PRIORITY_SETTINGS);}public void openDisplaySettings(){open(Settings.ACTION_DISPLAY_SETTINGS);}private void openPanel(String a){open(a);}private void open(String a){try{c.startActivity(new Intent(a).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){Toast.makeText(c,"Settings tidak tersedia",Toast.LENGTH_SHORT).show();}}}
